package DataConnection;

import com.sun.net.httpserver.HttpServer;
import org.glassfish.jersey.jackson.JacksonFeature;
import org.glassfish.jersey.jdkhttp.JdkHttpServerFactory;
import org.glassfish.jersey.server.ResourceConfig;
import java.net.URI;

public class Server {
    private static HttpServer server;

    // Startet den Server mit der angegebenen URL
    public static void startServer(String url) {
        if (server != null) {
            System.out.println("Server ist bereits gestartet.");
            return;
        }
        try {
            // Datenbankverbindung prüfen
            Util.getConnection("Hausverwaltung");

            final String pack = "dev.bsinfo.ressource";
            System.out.println("Start Server...");
            System.out.println("URL: " + url);

            // ResourceConfig mit allen benötigten Ressourcen
            final ResourceConfig rc = new ResourceConfig()
                    .packages(pack)
                    .register(JacksonFeature.class)
                    // Explizit die REST-Ressourcen registrieren
                    .register(dev.bsinfo.ressource.CustomerResource.class)
                    .register(dev.bsinfo.ressource.ReadingResource.class)
                    .register(dev.bsinfo.ressource.SetupResource.class);

            // Debug-Ausgabe der registrierten Ressourcen
            System.out.println("Registrierte Ressourcen:");
            rc.getClasses().forEach(System.out::println);

            // Server erstellen und starten
            server = JdkHttpServerFactory.createHttpServer(
                    URI.create(url),
                    rc
            );

            System.out.println("Server bereit für Anfragen auf " + url);
            System.out.println("Verfügbare Endpunkte:");
            System.out.println("- GET    " + url + "/customers");
            System.out.println("- POST   " + url + "/customers");
            System.out.println("- GET    " + url + "/readings");
            System.out.println("- POST   " + url + "/readings");
            System.out.println("- DELETE " + url + "/setupDB");

        } catch (Exception e) {
            System.err.println("Fehler beim Starten: " + e.getMessage());
            e.printStackTrace();
            throw new RuntimeException("Server konnte nicht gestartet werden", e);
        }
    }

    // Stoppt den Server
    public static void stopServer() {
        if (server == null) {
            System.out.println("Kein laufender Server, der gestoppt werden kann.");
            return;
        }
        server.stop(0);
        server = null;
        System.out.println("Server gestoppt");
    }

    // Hilfsmethoden für Tests
    public static HttpServer getServer() {
        return server;
    }

    public static int getServerCount() {
        return (server == null) ? 0 : 1;
    }
}

package DataConnection;

import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;

public class Util {
    //singleton
    private static Connection con = null;

    //factory methode
    public static Connection getConnection(final String db) {
        if (con == null) {
            try {
                String username = System.getProperty("user.name"); // Holt den aktuellen Benutzernamen
                String fullPath = System.getProperty("user.home") + File.separator + db + ".properties";
                System.out.println(fullPath);

                final Properties prop = new Properties();
                prop.load(new FileReader(fullPath));

                // Verwende den Benutzernamen als Prefix für die Properties
                final String dburl = prop.getProperty(username + ".db.url");
                final String dbuser = prop.getProperty(username + ".db.user");
                final String dbpw = prop.getProperty(username + ".db.pw");

                con = DriverManager.getConnection(dburl, dbuser, dbpw);

            } catch (SQLException | IOException e) {
                throw new RuntimeException(e);
            }
        }
        return con;
    }

    // close
    public static void close(final AutoCloseable obj) {
        if (obj != null) {
            try {
                obj.close();
            } catch (final Exception e) {
                // ignore
            }
        }
    }

    private Util() {
    }
}

package dev.bsinfo.ressource;

import DataConnection.Util;
import ReadingAndCustomer.*;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.stream.Collectors;

@Path("/customers")
public class CustomerResource {
    private final CustomerDAO customerDAO;
    private final ReadingDAO readingDAO;

    public CustomerResource() {
        this.customerDAO = new CustomerDAO(Util.getConnection("Hausverwaltung"));
        this.readingDAO = new ReadingDAO(Util.getConnection("Hausverwaltung"));
    }

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response createCustomer(Map<String, Customer> requestMap) {
        try {
            if (requestMap == null || !requestMap.containsKey("customer")) {
                Map<String, String> error = new HashMap<>();
                error.put("error", "Invalid request format. Expected: {\"customer\": {...}}");
                return Response.status(Response.Status.BAD_REQUEST)
                        .entity(error)
                        .build();
            }

            Customer customer = requestMap.get("customer");
            if (customer == null) {
                Map<String, String> error = new HashMap<>();
                error.put("error", "No customer data provided");
                return Response.status(Response.Status.BAD_REQUEST)
                        .entity(error)
                        .build();
            }

            if (customer.getId() == null) {
                customer.setId(UUID.randomUUID());
            }

            customerDAO.addCustomer(customer);
            Map<String, Object> response = new HashMap<>();
            response.put("customer", customer);
            return Response.status(Response.Status.CREATED)
                    .entity(response)
                    .build();
        } catch (Exception e) {
            Map<String, String> error = new HashMap<>();
            error.put("error", e.getMessage());
            return Response.status(Response.Status.BAD_REQUEST)
                    .entity(error)
                    .build();
        }
    }

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response getAllCustomers() {
        try {
            Map<String, Object> response = new HashMap<>();
            response.put("customers", customerDAO.getAllCustomers());
            return Response.ok(response).build();
        } catch (Exception e) {
            Map<String, String> error = new HashMap<>();
            error.put("error", e.getMessage());
            return Response.serverError()
                    .entity(error)
                    .build();
        }
    }

    @GET
    @Path("/{uuid}")
    @Produces(MediaType.APPLICATION_JSON)
    public Response getCustomer(@PathParam("uuid") String uuid) {
        try {
            ICustomer customer = customerDAO.getCustomerById(UUID.fromString(uuid));
            if (customer == null) {
                Map<String, String> error = new HashMap<>();
                error.put("error", "Customer not found");
                return Response.status(Response.Status.NOT_FOUND)
                        .entity(error)
                        .build();
            }
            Map<String, Object> response = new HashMap<>();
            response.put("customer", customer);
            return Response.ok(response).build();
        } catch (IllegalArgumentException e) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Invalid UUID format");
            return Response.status(Response.Status.BAD_REQUEST)
                    .entity(error)
                    .build();
        } catch (Exception e) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Customer not found");
            return Response.status(Response.Status.NOT_FOUND)
                    .entity(error)
                    .build();
        }
    }

    @PUT
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.TEXT_PLAIN)
    public Response updateCustomer(Map<String, Customer> requestMap) {
        try {
            if (requestMap == null || !requestMap.containsKey("customer")) {
                return Response.status(Response.Status.BAD_REQUEST)
                        .entity("Invalid request format. Expected: {\"customer\": {...}}")
                        .build();
            }

            Customer customer = requestMap.get("customer");
            if (customer == null || customer.getId() == null) {
                return Response.status(Response.Status.BAD_REQUEST)
                        .entity("Invalid customer data")
                        .build();
            }

            ICustomer existingCustomer = customerDAO.getCustomerById(customer.getId());
            if (existingCustomer == null) {
                return Response.status(Response.Status.NOT_FOUND)
                        .entity("Customer not found")
                        .build();
            }

            customerDAO.updateCustomer(customer);
            return Response.ok("Customer updated successfully").build();
        } catch (Exception e) {
            return Response.status(Response.Status.BAD_REQUEST)
                    .entity("Error: " + e.getMessage())
                    .build();
        }
    }

    @DELETE
    @Path("/{uuid}")
    @Produces(MediaType.APPLICATION_JSON)
    public Response deleteCustomer(@PathParam("uuid") String uuid) {
        try {
            UUID customerId = UUID.fromString(uuid);
            ICustomer customer = customerDAO.getCustomerById(customerId);
            if (customer == null) {
                Map<String, String> error = new HashMap<>();
                error.put("error", "Customer not found");
                return Response.status(Response.Status.NOT_FOUND)
                        .entity(error)
                        .build();
            }

            // Get customer's readings before deletion
            List<IReading> readings = readingDAO.getAllReadings().stream()
                    .filter(r -> r.getCustomer() != null && r.getCustomer().getId().equals(customerId))
                    .collect(Collectors.toList());

            customerDAO.deleteCustomer(customerId);

            Map<String, Object> response = new HashMap<>();
            response.put("customer", customer);
            response.put("readings", readings);
            return Response.ok(response).build();
        } catch (IllegalArgumentException e) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Invalid UUID format");
            return Response.status(Response.Status.BAD_REQUEST)
                    .entity(error)
                    .build();
        } catch (Exception e) {
            Map<String, String> error = new HashMap<>();
            error.put("error", e.getMessage());
            return Response.status(Response.Status.NOT_FOUND)
                    .entity(error)
                    .build();
        }
    }
}

