public class ReadingDAOTest {
    private static Connection connection;
    private static ReadingDAO readingDAO;
    private static CustomerDAO customerDAO;

    @BeforeAll
    public static void setUp() throws SQLException {
        // Verbindung zur MariaDB-Datenbank herstellen
        connection = DriverManager.getConnection(
                "jdbc:mariadb://localhost:3306/Hausverwaltung",
                "root",
                "Meerschweinchen20+");

        customerDAO = new CustomerDAO(connection);
        readingDAO = new ReadingDAO(connection);

        // Check if the table exists
        String tableName = "customer";
        String checkTableQuery = "SELECT COUNT(*) FROM information_schema.tables WHERE table_name = '" + tableName + "'";

        try (Statement stmt = connection.createStatement();
             ResultSet rs = stmt.executeQuery(checkTableQuery)) {

            boolean tableExists = rs.next() && rs.getInt(1) > 0;

            if (!tableExists) {
                customerDAO.createCustomerTable();
                readingDAO.createReadingTable();
            }
        }
    }

    @AfterAll
    static void closeDatabase() throws SQLException {
        connection.close();
    }

    @Test
    void testAddAndReadReading() throws SQLException {
        UUID meterId = UUID.randomUUID();

        // Reading erstellen
        IReading reading = new Reading(
                meterId,
                "Test comment",
                new Customer("Jane", "Doe", LocalDate.of(1990, 1, 1), ICustomer.Gender.W),
                LocalDate.of(2020, 1, 1),
                IReading.KindOfMeter.HEIZUNG,
                123.45,
                meterId.toString(),
                false
        );
        System.out.println(reading);

        // Add Reading
        readingDAO.addReading(reading);

        // Read Reading
        IReading retrievedReading = readingDAO.getReadingById(reading.getId());

        assertNotNull(retrievedReading);
        assertEquals(reading.getId(), retrievedReading.getId());
    }

    @AfterEach
    void cleanupDatabase() throws SQLException {
        // Lösche Testdaten nach jedem Test
        connection.createStatement().execute("DELETE FROM Reading");
        connection.createStatement().execute("DELETE FROM Customer");
    }

    @Test
    void testUpdateReading() throws SQLException {
        UUID meterId = UUID.randomUUID();
        UUID customerId = UUID.randomUUID();

        // Customer hinzufügen
        connection.createStatement().execute(
                "INSERT INTO Customer (id, firstName, lastName, birthDate, gender) VALUES (" +
                        "'" + customerId + "', 'Mark', 'Smith', '1980-05-15', 'M')"
        );


        // Reading erstellen
        IReading reading = new Reading(
                meterId,
                "Initial comment",
                new Customer("Mark", "Smith", LocalDate.of(1980, 5, 15), ICustomer.Gender.M),
                LocalDate.now(),
                IReading.KindOfMeter.STROM,
                200.0,
                meterId.toString(),
                true
        );

        // Add Reading
        readingDAO.addReading(reading);

        // Update Reading
        reading.setComment("Updated comment");
        reading.setMeterCount(250.0);
        readingDAO.updateReading(reading);

        // Verify Update
        IReading updatedReading = readingDAO.getReadingById(meterId);
        assertNotNull(updatedReading);
        assertEquals(200.0, updatedReading.getMeterCount());
    }

    @Test
    void testDeleteReading() throws SQLException {
        UUID meterId = UUID.randomUUID();
        UUID customerId = UUID.randomUUID();

        // Customer hinzufügen
        connection.createStatement().execute(
                "INSERT INTO Customer (id, firstName, lastName, birthDate, gender) VALUES (" +
                        "'" + customerId + "', 'Anna', 'Brown', '1995-10-10', 'F')"
        );

        // Reading erstellen
        IReading reading = new Reading(
                meterId,
                "To delete",
                new Customer("Anna", "Brown", LocalDate.of(1995, 10, 10), ICustomer.Gender.W),
                LocalDate.now(),
                IReading.KindOfMeter.WASSER,
                50.0,
                meterId.toString(),
                false
        );

        // Add Reading
        readingDAO.addReading(reading);

        // Delete Reading
        readingDAO.deleteReading(meterId);

        // Verify Deletion
        IReading deletedReading = readingDAO.getReadingById(meterId);
        assertNull(deletedReading);
    }

    @Test
    public void testGetAllReadings() throws SQLException {
        // Setup: Add some sample readings
        UUID meterId1 = UUID.randomUUID();
        UUID meterId2 = UUID.randomUUID();

        ICustomer customer = new Customer("John", "Doe", LocalDate.of(1990, 1, 1), ICustomer.Gender.M);
        customerDAO.addCustomer(customer);

        IReading reading1 = new Reading(
                meterId1,
                "First reading",
                customer,
                LocalDate.now(),
                IReading.KindOfMeter.STROM,
                100.0,
                meterId1.toString(),
                false
        );

        IReading reading2 = new Reading(
                meterId2,
                "Second reading",
                customer,
                LocalDate.now().minusDays(7),
                IReading.KindOfMeter.WASSER,
                50.0,
                meterId2.toString(),
                true
        );

        readingDAO.addReading(reading1);
        readingDAO.addReading(reading2);

        // Test: Get all readings
        List<IReading> allReadings = readingDAO.getAllReadings();

        // Assertions
        assertNotNull("All readings should not be null", String.valueOf(allReadings));
        assertEquals("Should return exactly two readings" + 2, "Should return exactly two readings" + allReadings.size());

        // Cleanup: Remove added readings
        readingDAO.deleteReading(reading1.getId());
        readingDAO.deleteReading(reading2.getId());
    }
}

import DataConnection.Util;
import ReadingAndCustomer.*;
import dev.bsinfo.ressource.ReadingResource;
import jakarta.ws.rs.core.Response;
import org.junit.jupiter.api.*;

import java.time.LocalDate;
import java.util.*;

import static org.junit.jupiter.api.Assertions.*;

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class ReadingResourceTest {

    private ReadingResource readingResource;
    private UUID testReadingId;
    private UUID testCustomerId;

    @BeforeAll
    void setup() {
        Util.getConnection("Hausverwaltung"); // Echte DB-Verbindung
        readingResource = new ReadingResource();
    }

    @Test
    @Order(1)
    void testCreateReading() {
        Map<String, Reading> request = new HashMap<>();
        Reading reading = new Reading();
        Customer customer = new Customer("Max", "Mustermann", LocalDate.of(1990, 5, 15), Customer.Gender.M);
        customer.setId(Optional.ofNullable(customer.getId()).orElse(UUID.randomUUID()));


        reading.setCustomer(customer);
        reading.setId(Optional.ofNullable(reading.getId()).orElse(UUID.randomUUID()));
        System.out.println("Reading ID: " + reading.getId());
        reading.setDateOfReading(LocalDate.now());
        reading.setKindOfMeter(IReading.KindOfMeter.HEIZUNG);
        reading.setMeterCount(123.45);
        reading.setSubstitute(false);
        request.put("reading", reading);

        Response response = readingResource.createReading(request);
        assertEquals(201, response.getStatus());

        Map<String, Object> responseBody = (Map<String, Object>) response.getEntity();
        assertNotNull(responseBody.get("reading"));
        testReadingId = ((Reading) responseBody.get("reading")).getId();
        testCustomerId = ((Reading) responseBody.get("reading")).getCustomer().getId();

        Reading createdReading = (Reading) responseBody.get("reading");
        assertNotNull(createdReading.getId());  // Sicherstellen, dass die ID zurückgegeben wird
        testReadingId = createdReading.getId();
        testCustomerId = createdReading.getCustomer().getId();

        System.out.println("Created Reading ID: " + testReadingId);
        testReadingId = reading.getId();
    }

    @Test
    @Order(2)
    void testCreateReadingBadRequest() {
        // Test: Fehlendes "reading"-Objekt
        Map<String, Reading> invalidRequest = new HashMap<>();
        Response response = readingResource.createReading(invalidRequest);
        assertEquals(400, response.getStatus());

        // Test: Fehlende Pflichtfelder (z.B. kein Customer)
        Map<String, Reading> requestWithoutCustomer = new HashMap<>();
        Reading reading = new Reading();
        reading.setId(UUID.randomUUID());
        reading.setDateOfReading(LocalDate.now());
        reading.setKindOfMeter(IReading.KindOfMeter.WASSER);
        reading.setMeterCount(100.0);
        requestWithoutCustomer.put("reading", reading);

        Response response2 = readingResource.createReading(requestWithoutCustomer);
        assertEquals(400, response2.getStatus());
    }

    @Test
    @Order(3)
    void testGetAllReadings() {
        Response response = readingResource.getReadings(null, null, null, null);
        assertEquals(200, response.getStatus());
    }

    @Test
    @Order(4)
    void testGetReadingById() {
        assertNotNull(testReadingId, "testReadingId should not be null");
        Response response = readingResource.getReading(testReadingId.toString());
        assertEquals(200, response.getStatus());
    }
    @Test
    @Order(5)
    void testGetReadingByIdBadRequest() {
        Response response = readingResource.getReading("invalid-uuid");

        // Akzeptiere sowohl 400 als auch 404, je nachdem, wie die API implementiert ist
        assertTrue(response.getStatus() == 400 || response.getStatus() == 404,
                "Expected 400 or 404, but got " + response.getStatus());
    }

    @Test
    @Order(6)
    void testUpdateReading() {
        Map<String, Reading> request = new HashMap<>();
        Reading reading = new Reading();
        reading.setId(testReadingId);
        reading.setCustomer(new Customer("Max", "Mustermann", LocalDate.of(1990, 5, 15), Customer.Gender.M));
        reading.setDateOfReading(LocalDate.now().minusDays(1));
        reading.setKindOfMeter(IReading.KindOfMeter.WASSER);
        reading.setMeterCount(200.00);
        reading.setSubstitute(false);
        request.put("reading", reading);

        assertNotNull(testReadingId, "testReadingId sollte nicht null sein!");
        Response response = readingResource.updateReading(request);
        assertEquals(200, response.getStatus());
        assertEquals("Reading updated successfully", response.getEntity());
//        System.out.println("Response Code: " + response.getStatus());
//        System.out.println("Response Body: " + response.getEntity());
    }
    @Test
    @Order(7)
    void testUpdateReadingBadRequest() {
        // Fehlendes "reading"-Objekt
        Map<String, Reading> invalidRequest = new HashMap<>();
        Response response = readingResource.updateReading(invalidRequest);
        assertEquals(400, response.getStatus());

        // Fehlende ID im Request
        Map<String, Reading> requestWithoutId = new HashMap<>();
        Reading reading = new Reading();
        reading.setCustomer(new Customer("Max", "Mustermann", LocalDate.of(1990, 5, 15), Customer.Gender.M));
        reading.setDateOfReading(LocalDate.now());
        reading.setKindOfMeter(IReading.KindOfMeter.WASSER);
        reading.setMeterCount(200.0);
        requestWithoutId.put("reading", reading);

        Response response2 = readingResource.updateReading(requestWithoutId);
        assertEquals(400, response2.getStatus());
    }

    @Test
    @Order(8)
    void testDeleteReading() {
        Response response = readingResource.deleteReading(testReadingId.toString());
        assertEquals(200, response.getStatus());
    }
    @Test
    @Order(9)
    void testDeleteReadingBadRequest() {
        Response response = readingResource.deleteReading("invalid-uuid");
        assertEquals(400, response.getStatus());
    }
}

